import"https://cdn.jsdelivr.net/npm/chart.js";const d="http://localhost:3000/api";document.getElementById("login-form").addEventListener("submit",async t=>{t.preventDefault();const r=t.target,s=document.getElementById("error-message"),e=r.querySelector('button[type="submit"]');s.classList.add("hidden"),e.disabled=!0,e.textContent="Ingresando...";const l=document.getElementById("email").value,c=document.getElementById("password").value;try{const o=await fetch(`${d}/auth/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:l,password:c})}),n=await o.json();if(!o.ok)throw new Error(n.error||"Error al iniciar sesión");localStorage.setItem("token",n.token),localStorage.setItem("user",JSON.stringify(n.user)),window.location.href="/dashboard"}catch(o){s.textContent=o.message,s.classList.remove("hidden"),e.disabled=!1,e.textContent="Ingresar"}});const a=document.querySelector(".login-header"),i=document.querySelector(".login-form"),m=document.querySelectorAll(".form-group");setTimeout(()=>{a.style.transition="all 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)",a.style.opacity="1",a.style.transform="translateY(0)"},100);setTimeout(()=>{i.style.transition="all 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94)",i.style.opacity="1",i.style.transform="translateY(0) scale(1)"},300);m.forEach((t,r)=>{setTimeout(()=>{t.style.transition="all 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94)",t.style.opacity="1",t.style.transform="translateX(0)"},500+r*100)});const u=localStorage.getItem("token");u&&(window.location.href="/dashboard");
